"""
Measurement only (David, 2026-10-28, item 1): the turn and the speed limit in PLACE: OVER (the carry). Nothing in src/ and no setting is changed.

    MUJOCO_GL=egl python experiments/place_over_turn_measure.py RECORDING_DIR [--t0 80.50 --t1 82.79]

One process. Phases:
 1. Replay of the recording (src/replay.py, states verified bit-identical). Between t0 (the place skill's start) and t1 (just before DOWN starts) every physics step records the left arm's
    command (ctrl), the pad centre and the pad frame. The joint state at t0 is kept.
 2. From the recorded commands (150 Hz): the pad's translation speed and turn rate, each joint's speed and where it sits at the solver's speed limit (MINK_CFG max_joint_speed).
 3. Dry runs of the same waypoint move on a scratch arm (MinkArm with the skill's settings, from the joint state at t0, the move's own timing formula, minimum-jerk profile, the phase-start
    speed cap, no sag correction, no physics): V0 as coded (checked against the recorded command), V1 turn limit halved (turn_rad_s 0.25), V2 turn in place first and then the straight move.
(e) Per-tick table of the first 1.5 s of the move (docs/reports/logs/place_over_turn_ticks_<name>.csv): the recorded command's velocity per joint, the joints at the speed limit, the reference
    velocity of the minimum-jerk profile, the sag correction and the tick-to-tick change of each velocity. The sag correction is not recorded, so it is rebuilt by a closed-loop dry run (V0 with
    the sag integral, driven by the recorded measured pad pose each tick); its commands are compared with the recorded ones.
Output: docs/reports/logs/place_over_turn_<name>.json (written to a temporary file, then renamed).
"""
import argparse
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
os.environ.setdefault("MUJOCO_GL", "egl")

import mink  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402
from scipy.spatial.transform import Rotation, Slerp  # noqa: E402

import src.replay as replay_mod  # noqa: E402
from src.gripper_geometry import gripper_frame  # noqa: E402
from src.mink_arm import MinkArm  # noqa: E402
from src.mpvi_modules import _clip_norm  # noqa: E402
from src.rate_limit import min_jerk  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_config import MINK_CFG, PICK_PLACE_CFG, TASK_CFG  # noqa: E402

DT = 1.0 / 150.0
LIMIT = MINK_CFG["max_joint_speed"]
AT_LIMIT = 0.99 * LIMIT          # rad/s: a joint counts as at the solver's speed limit above this


def replay_capture(recording, t0, t1):
    ctx, rows, snap = {}, [], {}

    def hook(step_count, data):
        if not ctx:
            m = MODEL[0]
            gf = gripper_frame(m, "left")
            ctx.update(tcp=m.body("openarm_left_hand_tcp").id, act=arm_ids(m, "left")["act"], pad=np.asarray(gf["pad_center_in_tcp"], float),
                       Rp=np.column_stack([gf["closing_axis"], np.cross(gf["approach_axis"], gf["closing_axis"]), gf["approach_axis"]]))
        if not (t0 <= data.time <= t1):
            return
        if "qpos" not in snap:
            snap["qpos"], snap["t"] = data.qpos.copy(), float(data.time)
        R = data.xmat[ctx["tcp"]].reshape(3, 3)
        rows.append((float(data.time), *data.ctrl[ctx["act"]], *(data.xpos[ctx["tcp"]] + R @ ctx["pad"]), *(R @ ctx["Rp"]).flatten()))

    MODEL = [None]
    orig = replay_mod.run_loop

    def spy(model, data, sources, cfg, viewer=None):
        MODEL[0] = model
        return orig(model, data, sources, cfg, viewer=viewer)

    replay_mod.run_loop = spy
    r = replay_mod.replay_run(Path(recording), out_dir=Path(os.environ.get("TMPDIR", "/tmp")) / "replay_turn_tmp", video="none", verify=True, quiet=True, step_hook=hook)
    replay_mod.run_loop = orig
    print(f"replay ok {r['ok']} ticks {r['ticks']} mismatch {r['mismatch']}", flush=True)
    return MODEL[0], np.array(rows), snap, r


def ticks(rows):
    """One row per control tick: t, q (7), pad p (3), pad R (3x3). The loop ramps the actuator command linearly across the 5 physics steps of a tick (control_loop ramp_from), so the command
    changes at every physics step; the tick boundaries are the rows where its slope changes, found as the offset (0..4) whose rows have the largest second differences."""
    q = rows[:, 1:8]
    d2 = np.abs(q[2:] - 2 * q[1:-1] + q[:-2]).sum(axis=1)             # row i + 1
    off = int(np.argmax([d2[(np.arange(len(d2)) + 1) % 5 == r].sum() for r in range(5)]))
    keep = np.arange(off, len(rows), 5)
    r = rows[keep]
    return r[:, 0], r[:, 1:8], r[:, 8:11], r[:, 11:20].reshape(-1, 3, 3)


def saturation(t, q, dt_each):
    """Per joint: peak speed, and the intervals (s from the start) where it is at the speed limit."""
    v = np.diff(q, axis=0) / dt_each[:, None]
    tm = t[1:] - t[0]
    out = {}
    for j in range(7):
        at = np.abs(v[:, j]) >= AT_LIMIT
        iv, start = [], None
        for i, a in enumerate(at):
            if a and start is None:
                start = i
            if not a and start is not None:
                iv.append((float(tm[start] - dt_each[start]), float(tm[i - 1])))
                start = None
        if start is not None:
            iv.append((float(tm[start] - dt_each[start]), float(tm[-1])))
        out[f"joint{j + 1}"] = {"peak_rad_s": float(np.abs(v[:, j]).max()), "at_limit_ticks": int(at.sum()), "at_limit_intervals_s": iv}
    return out, v


def dry_run(model, d, arm, segments, label, q_prev=None):
    """segments: list of (p0, R0, p1, R1, T). Each starts from rest with the phase-start cap. Returns the per-tick command and the report."""
    arm.reset(d)
    q = [arm.q_cmd.copy() if q_prev is None else np.asarray(q_prev, float).copy()]      # a skill start: the first step runs from the last command
    seg_end = []
    n_ramp = math.ceil(round(PICK_PLACE_CFG["phase_start_ramp_s"] / DT, 6))
    for seg in segments:
        p0, R0, p1, R1, T = seg
        sl = Slerp([0.0, 1.0], Rotation.from_matrix([R0, R1]))
        n = int(math.ceil(T / DT)) + int(round(0.3 / DT))                 # the move, then 0.3 s of hold (the settle dwell's start)
        for k in range(n):
            el = k * DT
            s = min_jerk(min(el / T, 1.0))
            before = arm.q_cmd.copy() if (k > 0 or q_prev is None or segments[0] is not seg) else q_prev      # a skill start: the ramp runs from the last command (the snap to the measured joints goes through it)
            arm.step(d, p0 + (p1 - p0) * s, sl(s).as_matrix())
            if k < n_ramp:
                env = LIMIT * min_jerk((k + 1) * DT / PICK_PLACE_CFG["phase_start_ramp_s"])
                v = np.clip((arm.q_cmd - before) / DT, -env, env)
                arm.q_cmd = before + v * DT
            q.append(arm.q_cmd.copy())
        seg_end.append(len(q) - 1)
    q = np.array(q)
    t = np.arange(len(q)) * DT
    sat, v = saturation(t, q, np.full(len(q) - 1, DT))
    return {"label": label, "q": q, "seg_end_idx": seg_end, "saturation": sat, "peak_speed_rad_s": float(np.abs(v).max())}


def closed_loop(arm, d, pp, pR, p0, R0, p1, R1, T, shift, q_prev):
    """V0 with the skill's sag integral, the measured pad pose of each tick taken from the recording. Returns q (n+1, 7), the sag position and rotation corrections (n, 3), (n, 3), the cap (n,)."""
    cfg = PICK_PLACE_CFG
    arm.reset(d)
    sl = Slerp([0.0, 1.0], Rotation.from_matrix([R0, R1]))
    Cp, Cr = np.zeros(3), np.zeros(3)
    n_ramp = math.ceil(round(cfg["phase_start_ramp_s"] / DT, 6))
    q, sp, sr, cap = [arm.q_cmd.copy()], [], [], []
    for k in range(len(pp) - 1 - max(shift, 0)):
        el = k * DT
        s = min_jerk(min(el / T, 1.0))
        p_ref, R_ref = p0 + (p1 - p0) * s, sl(s).as_matrix()
        i = min(max(k + shift, 0), len(pp) - 1)
        p_now, R_now = pp[i], pR[i]
        Cp = _clip_norm(Cp + cfg["sag_gain_per_s"] * (p_ref - p_now) * DT, cfg["sag_max_m"])
        Cr = _clip_norm(Cr + cfg["sag_gain_per_s"] * Rotation.from_matrix(R_ref @ R_now.T).as_rotvec() * DT, cfg["sag_max_rad"])
        before = arm.q_cmd.copy() if k > 0 else q_prev
        arm.step(d, p_ref + Cp, (Rotation.from_rotvec(Cr) * Rotation.from_matrix(R_ref)).as_matrix())
        env = LIMIT * min_jerk((k + 1) * DT / cfg["phase_start_ramp_s"]) if k < n_ramp else np.inf
        if k < n_ramp:
            arm.q_cmd = before + np.clip((arm.q_cmd - before) / DT, -env, env) * DT
        q.append(arm.q_cmd.copy())
        sp.append(Cp.copy())
        sr.append(Cr.copy())
        cap.append(env)
    return np.array(q), np.array(sp), np.array(sr), np.array(cap)


def planned_T(arm, d, p0, R0, p1, R1, speed, turn_rad_s):
    dist = float(np.linalg.norm(p1 - p0))
    ang = float(np.linalg.norm(Rotation.from_matrix(R0.T @ R1).as_rotvec()))
    us = np.linspace(0.0, 1.0, PICK_PLACE_CFG["arc_points"] + 1)
    sl = Slerp([0.0, 1.0], Rotation.from_matrix([R0, R1]))
    arc, end = arm.joint_arc(d, p0 + np.outer(us, p1 - p0), sl(us).as_matrix())
    parts = {"min_move_s": PICK_PLACE_CFG["min_move_s"], "distance_s": dist / speed, "turn_s": ang / turn_rad_s,
             "joint_limit_s": PICK_PLACE_CFG["min_jerk_peak_factor"] * float(arc.max()) / LIMIT}
    T = max(parts.values())
    return T, parts, dist, ang, arc


def main(a):
    model, rows, snap, rep = replay_capture(a.recording, a.t0, a.t1)
    t, q, pp, pR = ticks(rows)
    dts = np.diff(t)
    out = {"recording": str(a.recording), "replay_ok": bool(rep["ok"]), "t0": a.t0, "t1": a.t1, "snapshot_time": snap["t"], "ticks": int(len(t)), "limit_rad_s": LIMIT}
    # --- recorded run ---
    p0, R0, p1, R1 = pp[0], pR[0], pp[-1], pR[-1]
    turn_total = float(np.degrees(np.linalg.norm(Rotation.from_matrix(R0.T @ R1).as_rotvec())))
    vtr = np.linalg.norm(np.diff(pp, axis=0), axis=1) / dts
    rel = np.array([Rotation.from_matrix(pR[i].T @ pR[i + 1]).magnitude() for i in range(len(pR) - 1)])
    wturn = np.degrees(rel) / dts
    move_end = a.t0 + 1.68
    in_move = (t[1:] - a.t0) <= (move_end - a.t0)
    out["recorded"] = {"translation_m": float(np.linalg.norm(p1 - p0)), "turn_total_deg": turn_total,
                       "translation_peak_mm_s": float(1000 * vtr[in_move].max()), "translation_mean_mm_s_over_1.68s": float(1000 * np.linalg.norm(p1 - p0) / 1.68),
                       "turn_peak_deg_s": float(wturn[in_move].max()), "turn_mean_deg_s_over_1.68s": float(turn_total / 1.68),
                       "turn_limit_deg_s": float(np.degrees(PICK_PLACE_CFG["turn_rad_s"])), "translation_limit_mm_s": 1000 * PICK_PLACE_CFG["speed_m_s"]}
    sat, v = saturation(t, q, dts)
    out["recorded"]["joints"] = sat
    out["recorded"]["peak_joint_speed_rad_s"] = float(np.abs(v).max())
    # --- dry runs ---
    d = mujoco.MjData(model)
    d.qpos[:] = snap["qpos"]
    mujoco.mj_forward(model, d)
    arm = MinkArm(model, d, "left", np.asarray(TASK_CFG["home_q_left"], float))
    arm.reset(d)
    ps, Rs = arm.pad_pose(d)
    out["dry_start_vs_recorded_start_mm"] = float(1000 * np.linalg.norm(ps - p0))
    # the target: the pad pose reached (the move's waypoint within tolerance) at the end of the recording window
    T0, parts, dist, ang, arc = planned_T(arm, d, ps, Rs, p1, R1, PICK_PLACE_CFG["speed_m_s"], PICK_PLACE_CFG["turn_rad_s"])
    out["V0_planned"] = {"T_s": T0, "parts_s": parts, "distance_m": dist, "turn_deg": math.degrees(ang), "joint_arc_rad": arc.tolist()}
    r0 = dry_run(model, d, arm, [(ps, Rs, p1, R1, T0)], "V0", q_prev=q[0])
    arm.reset(d)
    T1, parts1, *_ = planned_T(arm, d, ps, Rs, p1, R1, PICK_PLACE_CFG["speed_m_s"], 0.5 * PICK_PLACE_CFG["turn_rad_s"])
    r1 = dry_run(model, d, arm, [(ps, Rs, p1, R1, T1)], "V1", q_prev=q[0])
    # V2: turn in place, then the straight move at the turned hand
    arm.reset(d)
    TA, partsA, _, angA, arcA = planned_T(arm, d, ps, Rs, ps, R1, PICK_PLACE_CFG["speed_m_s"], PICK_PLACE_CFG["turn_rad_s"])
    arm.reset(d)
    dA = mujoco.MjData(model)                                         # the second leg's planning starts from the first leg's end: take its joints
    r2a = dry_run(model, d, arm, [(ps, Rs, ps, R1, TA)], "V2a", q_prev=q[0])
    dA.qpos[:] = d.qpos
    dA.qpos[arm.qadr] = r2a["q"][r2a["seg_end_idx"][0]]
    mujoco.mj_forward(model, dA)
    armB = MinkArm(model, dA, "left", np.asarray(TASK_CFG["home_q_left"], float))
    armB.reset(dA)
    pB, RB = armB.pad_pose(dA)
    TB, partsB, distB, _, arcB = planned_T(armB, dA, pB, RB, p1, R1, PICK_PLACE_CFG["speed_m_s"], PICK_PLACE_CFG["turn_rad_s"])
    r2b = dry_run(model, dA, armB, [(pB, RB, p1, R1, TB)], "V2b")
    cmp = {}
    for key, r, T in (("V0", r0, T0), ("V1", r1, T1)):
        cmp[key] = {"T_s": T, "peak_speed_rad_s": r["peak_speed_rad_s"], "saturation": r["saturation"],
                    "end_pad_err_mm": None}
    cmp["V1"]["parts_s"] = parts1
    cmp["V2"] = {"T_turn_s": TA, "parts_turn_s": partsA, "T_straight_s": TB, "parts_straight_s": partsB, "T_total_s": TA + TB, "turn_deg": math.degrees(angA), "straight_m": distB,
                 "turn_leg": {"peak_speed_rad_s": r2a["peak_speed_rad_s"], "saturation": r2a["saturation"]},
                 "straight_leg": {"peak_speed_rad_s": r2b["peak_speed_rad_s"], "saturation": r2b["saturation"]}}
    # V0 against the record: the commanded joints over the move
    n = min(len(r0["q"]), len(q))
    out["V0_vs_recorded_max_joint_diff_rad"] = float(np.abs(r0["q"][:n] - q[:n]).max())
    out["variants"] = cmp
    # --- (e) the per-tick table ---
    best = None
    for shift in (-1, 0, 1):
        qc, sp, sr, cap = closed_loop(arm, d, pp, pR, ps, Rs, p1, R1, T0, shift, q[0])
        m = min(len(qc), len(q))
        err = float(np.abs(qc[:m] - q[:m]).max())
        if best is None or err < best[0]:
            best = (err, shift, qc, sp, sr, cap)
    err, shift, qc, sp, sr, cap = best
    out["closed_loop_vs_recorded_max_joint_diff_rad"], out["closed_loop_tick_shift"] = err, shift
    n = int(round(1.5 / DT))
    n = min(n, len(q) - 1, len(sp))
    sl = Slerp([0.0, 1.0], Rotation.from_matrix([Rs, R1]))
    lines = ["tick,t_rel_s,u,at_limit_joints,at_ramp_cap_joints,cmd_v1,cmd_v2,cmd_v3,cmd_v4,cmd_v5,cmd_v6,cmd_v7,ramp_cap_rad_s,ref_trans_mm_s,ref_turn_deg_s,sag_pos_mm,sag_rot_deg,max_dv_rad_s,max_dv_joint,rebuilt_minus_recorded_max_rad"]
    for k in range(n):
        vk = (q[k + 1] - q[k]) / dts[k]
        u = min(k * DT / T0, 1.0)
        ds = (30 * u ** 2 - 60 * u ** 3 + 30 * u ** 4) / T0                  # d(min_jerk)/dt, 1/s
        ref_tr = 1000 * dist * ds
        ref_turn = math.degrees(ang) * ds
        capk = ",".join(f"J{j + 1}" for j in range(7) if np.isfinite(cap[k]) and abs(vk[j]) >= 0.97 * cap[k] and cap[k] < LIMIT) or "-"
        lim = ",".join(f"J{j + 1}" for j in range(7) if abs(vk[j]) >= AT_LIMIT) or "-"
        dv = np.abs(vk - (q[k] - q[k - 1]) / dts[k - 1]) if k > 0 else np.zeros(7)
        lines.append(",".join([str(k), f"{k * DT:.4f}", f"{u:.4f}", lim.replace(",", "+"), capk.replace(",", "+")] + [f"{x:.4f}" for x in vk] +
                              [f"{cap[k]:.4f}" if np.isfinite(cap[k]) else "-", f"{ref_tr:.2f}", f"{ref_turn:.3f}", f"{1000 * np.linalg.norm(sp[k]):.3f}",
                               f"{math.degrees(np.linalg.norm(sr[k])):.4f}", f"{dv.max():.4f}", f"J{int(dv.argmax()) + 1}", f"{np.abs(qc[k + 1] - q[k + 1]).max():.5f}"]))
    csv_tmp = PROJECT_ROOT / "docs" / "reports" / "logs" / f"place_over_turn_ticks_{a.name}.csv.tmp"
    csv_tmp.write_text("\n".join(lines) + "\n")
    os.replace(csv_tmp, csv_tmp.with_suffix(""))
    tmp = PROJECT_ROOT / "docs" / "reports" / "logs" / f"place_over_turn_{a.name}.json.tmp"
    tmp.parent.mkdir(parents=True, exist_ok=True)
    tmp.write_text(json.dumps(out, indent=1))
    os.replace(tmp, tmp.with_suffix(""))
    print(json.dumps({k: v for k, v in out.items() if k not in ("variants",)}, indent=1)[:6000])
    print(json.dumps(out["variants"], indent=1)[:9000])
    return 0 if rep["ok"] else 1


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("recording")
    ap.add_argument("--t0", type=float, default=80.50)
    ap.add_argument("--t1", type=float, default=82.79)
    ap.add_argument("--name", default="smoothmj")
    sys.exit(main(ap.parse_args()))
